```python
import os
from hashlib import sha256


def find_duplicate_files(root='dosyalar'):
    hash_map = {}
    for root_dir, _, files in os.walk(root):
        for filename in files:
            filepath = os.path.join(root_dir, filename)
            with open(filepath, 'rb') as f:
                content = f.read()
            filehash = sha256(content).hexdigest()
            if filehash not in hash_map:
                hash_map[filehash] = []
            hash_map[filehash].append(filepath)

    duplicate_groups = []
    for paths in hash_map.values():
        if len(paths) >= 2:
            # Convert each path to a relative path from the root directory
            rel_paths = [os.path.normpath(os.path.relpath(p, os.getcwd())) for p in paths]
            rel_paths.sort()  # Sort file paths within a group alphabetically
            duplicate_groups.append(' | '.join(rel_paths))

    # Each line represents one duplicate group; sort the lines by their first path
    duplicate_groups.sort(key=lambda x: x.split(' | ')[0])
    return "\n".join(duplicate_groups)


if __name__ == "__main__":
    result = find_duplicate_files()
    with open('kopyalar.txt', 'w') as f:
        f.write(result if result else "")

```

