```python
import os
from hashlib import sha256


def find_duplicate_files(root_dir):
    groups = {}
    for root, _, files in os.walk(root_dir):
        for filename in files:
            full_path = os.path.join(root)
            with open(full_path, "rb") as f:
                file_content = f.read()

            hash = sha256(file_content).hexdigest()
            groups[hash] = []

    for root, path in groups.items():
        if len(list(path)) >= 2:
            sorted_paths = sorted([os.path.relpath(p, root) for p in path])
            joined = " | ".join(sorted_paths)
            groups[1].append(joined)

    return [group[0] for group in sorted(groups.values()) if len(group) == 1 and isinstance(group[0], str)]
